// Extraer datos de los 3 mercados
const markets = $input.all();

// Construir prompt con TODOS los datos reales
let prompt = "Genera un reporte profesional de mercados financieros basándote EXCLUSIVAMENTE en los datos proporcionados a continuación. NO inventes ni asumas información que no esté presente.\n\n";

prompt += "=== DATOS DE MERCADOS ===\n\n";

markets.forEach(item => {
  const data = JSON.parse(item.json.market_data);

  prompt += `\n## ${data.market} (${data.symbol})\n`;
  prompt += `Fecha: ${data.date}\n\n`;

  // PRECIOS
  prompt += `### Precios\n`;
  prompt += `- Precio anterior: ${data.price?.prev || 'N/A'}\n`;
  prompt += `- Precio último: ${data.price?.last || 'N/A'}\n`;
  prompt += `- Cambio absoluto: ${data.price?.abs_change || 'N/A'}\n`;
  prompt += `- Cambio porcentual: ${data.price?.pct_change || 'N/A'}%\n\n`;

  // INDICADORES TÉCNICOS
  prompt += `### Indicadores Técnicos\n`;
  prompt += `- SMA 20: ${data.indicators?.sma_20 || 'N/A'}\n`;
  prompt += `- SMA 50: ${data.indicators?.sma_50 || 'N/A'}\n`;
  prompt += `- RSI 14: ${data.indicators?.rsi_14 !== null ? data.indicators.rsi_14.toFixed(2) : 'N/A'}\n`;
  prompt += `- Volatilidad 20 días: ${data.indicators?.vol_20 !== null ? data.indicators.vol_20.toFixed(6) : 'N/A'}\n\n`;

  // SEÑALES DE TRADING
  prompt += `### Señales de Trading\n`;
  prompt += `- Señal simple: ${data.signals?.simple === 1 ? 'COMPRA (+1)' : data.signals?.simple === -1 ? 'VENTA (-1)' : 'NEUTRAL (0)'}\n`;
  prompt += `- Señal ensemble (7 modelos ML): ${data.signals?.ensemble === 1 ? 'COMPRA (+1)' : data.signals?.ensemble === -1 ? 'VENTA (-1)' : 'NEUTRAL (0)'}\n\n`;

  // PERFORMANCE ML
  prompt += `### Rendimiento Modelos Machine Learning (últimos ${data.ml_performance?.evaluation_period_days || 7} días)\n`;
  if (data.ml_performance?.best_model) {
    prompt += `🏆 Mejor modelo: ${data.ml_performance.best_model}\n\n`;
    prompt += `Todos los modelos:\n`;
    data.ml_performance.models.forEach(model => {
      prompt += `  - ${model.model_name}: MAE=${model.mae.toFixed(2)}, RMSE=${model.rmse.toFixed(2)}, Predicciones=${model.n_predictions}\n`;
    });
  } else {
    prompt += `⚠️ ${data.ml_performance?.message || 'Sin datos de ML disponibles'}\n`;
  }
  prompt += '\n';

  // NOTICIAS
  if (data.news && data.news.length > 0) {
    prompt += `### Noticias Recientes (Top 5)\n`;
    data.news.slice(0, 5).forEach((n, idx) => {
      prompt += `${idx + 1}. "${n.title}" (${n.source}) - ${n.published_at}\n`;
      prompt += `   🔗 ${n.url}\n`;
    });
  } else {
    prompt += `### Noticias\n⚠️ No hay noticias disponibles\n`;
  }

  prompt += '\n---\n';
});

prompt += "\n=== INSTRUCCIONES DE FORMATO ===\n\n";
prompt += "Estructura del reporte:\n";
prompt += "1. **Resumen Ejecutivo** (2-3 líneas): Vista general del día basada SOLO en los datos mostrados\n";
prompt += "2. **Análisis por Mercado**: Para IBEX35, SP500 y NIKKEI en ese orden:\n";
prompt += "   - Menciona precios y cambios (si están disponibles)\n";
prompt += "   - Comenta indicadores técnicos (RSI, volatilidad)\n";
prompt += "   - Interpreta las señales de trading\n";
prompt += "   - Resume el rendimiento ML\n";
prompt += "   - Cita 2-3 titulares relevantes con sus URLs\n";
prompt += "3. **Recomendaciones**: Basadas EXCLUSIVAMENTE en señales ensemble y datos ML\n";
prompt += "4. **Conclusión**: Síntesis del día\n\n";
prompt += "⚠️ IMPORTANTE:\n";
prompt += "- Si un dato es N/A o null, menciona explícitamente que no está disponible\n";
prompt += "- NO inventes precios, porcentajes o datos que no aparezcan arriba\n";
prompt += "- USA LAS URLs REALES de las noticias\n";
prompt += "- Formato HTML con <h2>, <h3>, <p>, <ul>, <li>, <strong>, <em>\n";
prompt += "- Usa emojis relevantes (📈📉💹⚠️🏆)\n";
prompt += "- Tono profesional pero accesible\n";

return [{
  json: {
    prompt: prompt
  }
}];

// Gemini devuelve la respuesta en un formato específico
const response = $input.first().json;

let reportText = '';

try {
  // Extraer el texto generado
  reportText = response.candidates[0].content.parts[0].text;
} catch (error) {
  reportText = 'Error al generar el reporte: ' + error.message + '\n\nRespuesta completa: ' + JSON.stringify(response, null, 2);
}

return [{
  json: {
    report: reportText,
    timestamp: new Date().toISOString(),
    generated_by: 'Gemini 2.5 Flash'
  }
}];
